package io.blert.challenges.colosseum;

import io.blert.core.*;
import io.blert.events.NpcAttackEvent;
import io.blert.events.colosseum.*;
import io.blert.util.ChatText;
import io.blert.util.Tick;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import org.apache.commons.lang3.tuple.Pair;

@Slf4j
public class WaveDataTracker extends DataTracker {
    private static final String bossStartMessage = "Sol Heredit jumps down from his seat...";
    private final String waveStartMessage;
    private final Pattern waveEndRegex;

    private final int ticksOnEntry;

    @Setter
    private Handicap handicap;

    @Setter
    private Handicap[] handicapOptions;

    private static final int REENTRY_PRIMARY_GAME_OBJECT_ID = 50743;
    private static final int REENTRY_SECONDARY_GROUND_OBJECT_ID = 50744;
    private static final int HEALING_TOTEM_PROJECTILE_ID = 2687;
    private static final Set<Integer> SOL_DUST_GRAPHIC_OBJECT_IDS = Set.of(2669, 2670, 2671);
    private static final Set<Integer> SOL_LASER_SCAN_GRAPHIC_OBJECT_IDS = Set.of(2689, 2690, 2691);
    private static final Set<Integer> SOL_LASER_SHOT_GRAPHIC_OBJECT_IDS = Set.of(2693, 2694, 2695);
    private static final int SOL_POOL_GRAPHIC_OBJECT_ID = 2698;

    private final Map<WorldPoint, NPC> healingTotems = new HashMap<>();
    private final Map<NPC, Pair<NPC, Integer>> activeHeals = new HashMap<>();

    private final List<GameObject> reentryPrimaryPoolsSpawned = new ArrayList<>();
    private final List<GroundObject> reentrySecondaryPoolsSpawned = new ArrayList<>();
    private final List<GameObject> reentryPrimaryPoolsDespawned = new ArrayList<>();
    private final List<GroundObject> reentrySecondaryPoolsDespawned = new ArrayList<>();
    private final Set<WorldPoint> solDustGraphics = new HashSet<>();
    private final List<WorldPoint> solPools = new ArrayList<>();
    private GraphicsObject solLaserGraphic;

    private static final Map<String, EquipmentSlot> GRAPPLE_MESSAGES = Map.of(
            "Sol Heredit: I'LL CRUSH YOUR BODY!", EquipmentSlot.TORSO,
            "Sol Heredit: I'LL BREAK YOUR BACK!", EquipmentSlot.CAPE,
            "Sol Heredit: I'LL TWIST YOUR HANDS OFF!", EquipmentSlot.GLOVES,
            "Sol Heredit: I'LL BREAK YOUR LEGS!", EquipmentSlot.LEGS,
            "Sol Heredit: I'LL CUT YOUR FEET OFF!", EquipmentSlot.BOOTS);
    private static final String GRAPPLE_DEFEND_MESSAGE = "You successfully defend from Sol Heredit's grapple!";
    private static final String GRAPPLE_PARRY_MESSAGE = "You perfectly parry Sol Heredit's grapple!";

    private @Nullable EquipmentSlot pendingGrappleTarget = null;
    private int pendingGrappleTick = -1;

    public static Stage waveToStage(int wave) {
        return Stage.values()[Stage.COLOSSEUM_WAVE_1.ordinal() + wave - 1];
    }

    public WaveDataTracker(RecordableChallenge challenge, Client client, int wave, int ticksOnEntry) {
        super(challenge, client, waveToStage(wave));

        this.waveStartMessage = "Wave: " + wave;
        this.waveEndRegex =
                Pattern.compile("Wave " + wave + " completed! " + "Wave duration: (" + Tick.TIME_STRING_REGEX + ")");
        this.ticksOnEntry = ticksOnEntry;
    }

    @Override
    protected Optional<? extends TrackedNpc> onNpcSpawn(NpcSpawned event) {
        return ColosseumNpc.withId(event.getNpc().getId()).map(colosseumNpc -> {
            NPC npc = event.getNpc();
            if (colosseumNpc.isHealingTotem()) {
                healingTotems.put(npc.getWorldLocation(), npc);
            }
            if (colosseumNpc.isManticore()) {
                return new Manticore(npc, generateRoomId(npc), new Hitpoints(colosseumNpc.getHitpoints()));
            }
            return new BasicTrackedNpc(npc, generateRoomId(npc), new Hitpoints(colosseumNpc.getHitpoints()));
        });
    }

    @Override
    protected boolean onNpcDespawn(NpcDespawned event, @Nullable TrackedNpc trackedNpc) {
        if (trackedNpc != null) {
            if (ColosseumNpc.withId(trackedNpc.getNpc().getId())
                    .map(ColosseumNpc::isHealingTotem)
                    .orElse(false)) {
                healingTotems.remove(trackedNpc.getNpc().getWorldLocation());
            }
            activeHeals.remove(trackedNpc.getNpc());
        }
        return ColosseumNpc.withId(event.getNpc().getId()).isPresent();
    }

    @Override
    protected void onAnimation(AnimationChanged event) {
        if (!(event.getActor() instanceof NPC)) {
            return;
        }

        NPC npc = (NPC) event.getActor();
        Optional<ColosseumNpc> maybeNpc = ColosseumNpc.withId(npc.getId());
        Optional<TrackedNpc> maybeTrackedNpc = getTrackedNpcs().getByNpc(npc);
        if (maybeNpc.isEmpty() || maybeTrackedNpc.isEmpty() || npc.getAnimation() == -1) {
            return;
        }

        ColosseumNpc colosseumNpc = maybeNpc.get();
        TrackedNpc trackedNpc = maybeTrackedNpc.get();

        if (colosseumNpc.isManticore()) {
            Manticore manticore = (Manticore) trackedNpc;
            if (npc.getAnimation() == Manticore.ATTACK_ANIMATION) {
                manticore.startAttack();
            }
            return;
        }

        colosseumNpc.getAttack(npc.getAnimation()).ifPresent(attack -> {
            WorldPoint location = getWorldLocation(npc);
            dispatchEvent(new NpcAttackEvent(getStage(), getTick(), location, attack, trackedNpc));
        });
    }

    @Override
    protected void onTick() {
        if (notStarted()) {
            return;
        }

        getTrackedNpcs().stream()
                .filter(trackedNpc -> trackedNpc instanceof Manticore)
                .forEach(trackedNpc -> {
                    Manticore manticore = (Manticore) trackedNpc;
                    // Check for an attack using the previous tick's style before updating.
                    NpcAttack attack = manticore.continueAttack();
                    if (attack != null) {
                        WorldPoint location = getWorldLocation(manticore.getNpc());
                        dispatchEvent(new NpcAttackEvent(getStage(), getTick(), location, attack, manticore));
                    }
                    manticore.updateStyle();
                });

        sendReentryPoolsEvent();

        if (getStage() == Stage.COLOSSEUM_WAVE_12) {
            handleSolEvents();
        }

        reentryPrimaryPoolsSpawned.clear();
        reentrySecondaryPoolsSpawned.clear();
        reentryPrimaryPoolsDespawned.clear();
        reentrySecondaryPoolsDespawned.clear();
        solDustGraphics.clear();
        solPools.clear();
        solLaserGraphic = null;
    }

    @Override
    protected void onHitsplat(HitsplatApplied event) {
        Actor actor = event.getActor();
        Hitsplat hitsplat = event.getHitsplat();
        if (actor == client.getLocalPlayer()) {
            if (hitsplat.getHitsplatType() == HitsplatID.DOOM) {
                dispatchEvent(new DoomAppliedEvent(getStage(), getTick(), getWorldLocation(actor)));
            }
            return;
        }

        if (actor instanceof NPC && hitsplat.getHitsplatType() == HitsplatID.HEAL) {
            var activeHeal = activeHeals.get(actor);
            if (activeHeal == null) {
                return;
            }

            Optional<TrackedNpc> totem = getTrackedNpcs().getByNpc(activeHeal.getLeft());
            Optional<TrackedNpc> target = getTrackedNpcs().getByNpc((NPC) actor);
            if (totem.isPresent() && target.isPresent()) {
                dispatchEvent(new TotemHealEvent(
                        getStage(),
                        getTick(),
                        getWorldLocation(actor),
                        totem.get(),
                        target.get(),
                        activeHeal.getRight(),
                        hitsplat.getAmount()));
            }
        }
    }

    @Override
    protected void onProjectile(ProjectileMoved event) {
        Projectile projectile = event.getProjectile();
        if (projectile.getId() != HEALING_TOTEM_PROJECTILE_ID) {
            return;
        }

        NPC totem = healingTotems.get(projectile.getSourcePoint());
        if (totem == null) {
            return;
        }

        Actor target = projectile.getTargetActor();
        if (!(target instanceof NPC)) {
            return;
        }

        int cycle = client.getGameCycle() - projectile.getStartCycle();
        if (cycle == 0) {
            getTrackedNpcs().getByNpc((NPC) target).ifPresent(npc -> {
                activeHeals.put(npc.getNpc(), Pair.of(totem, getTick()));
            });
        }
    }

    @Override
    protected void onGameObjectSpawn(GameObjectSpawned event) {
        GameObject object = event.getGameObject();
        if (object.getId() == REENTRY_PRIMARY_GAME_OBJECT_ID) {
            reentryPrimaryPoolsSpawned.add(object);
        }
    }

    @Override
    protected void onGameObjectDespawn(GameObjectDespawned event) {
        GameObject object = event.getGameObject();
        if (object.getId() == REENTRY_PRIMARY_GAME_OBJECT_ID) {
            reentryPrimaryPoolsDespawned.add(object);
        }
    }

    @Override
    protected void onGroundObjectSpawn(GroundObjectSpawned event) {
        GroundObject object = event.getGroundObject();
        if (object.getId() == REENTRY_SECONDARY_GROUND_OBJECT_ID) {
            reentrySecondaryPoolsSpawned.add(object);
        }
    }

    @Override
    protected void onGroundObjectDespawn(GroundObjectDespawned event) {
        GroundObject object = event.getGroundObject();
        if (object.getId() == REENTRY_SECONDARY_GROUND_OBJECT_ID) {
            reentrySecondaryPoolsDespawned.add(object);
        }
    }

    @Override
    protected void onGraphicsObjectCreation(GraphicsObjectCreated event) {
        GraphicsObject object = event.getGraphicsObject();
        if (SOL_DUST_GRAPHIC_OBJECT_IDS.contains(object.getId())) {
            solDustGraphics.add(getWorldLocation(object));
        } else if (object.getId() == SOL_POOL_GRAPHIC_OBJECT_ID) {
            solPools.add(getWorldLocation(object));
        } else if (SOL_LASER_SCAN_GRAPHIC_OBJECT_IDS.contains(object.getId())
                || SOL_LASER_SHOT_GRAPHIC_OBJECT_IDS.contains(object.getId())) {
            // Scans and shots should never happen on the same tick but if it somehow occurs,
            // prioritize a shot, which has a higher ID.
            if (solLaserGraphic == null || object.getId() > solLaserGraphic.getId()) {
                solLaserGraphic = object;
            }
        }
    }

    @Override
    protected void onMessage(ChatMessage event) {
        String stripped = ChatText.stripFormatting(event.getMessage());

        if (stripped.equals(waveStartMessage)) {
            startWave(0);
            return;
        }
        if (stripped.equals(bossStartMessage)) {
            startWave(-1);
            return;
        }

        if (getStage() == Stage.COLOSSEUM_WAVE_12) {
            EquipmentSlot grappleSlot = GRAPPLE_MESSAGES.get(stripped);
            if (grappleSlot != null) {
                pendingGrappleTarget = grappleSlot;
                pendingGrappleTick = getTick();
                return;
            }

            if (pendingGrappleTarget != null) {
                if (stripped.equals(GRAPPLE_DEFEND_MESSAGE)) {
                    dispatchGrapple(SolGrappleEvent.Outcome.DEFEND);
                    return;
                }
                if (stripped.equals(GRAPPLE_PARRY_MESSAGE)) {
                    dispatchGrapple(SolGrappleEvent.Outcome.PARRY);
                    return;
                }
            }

            Matcher matcher = ColosseumChallenge.COLOSSEUM_END_REGEX.matcher(stripped);
            if (matcher.find()) {
                try {
                    var ticks = Tick.fromTimeString(matcher.group(1));
                    if (ticks.isPresent()) {
                        int challengeTicks = ticks.get().getLeft();
                        int bossTicks = challengeTicks - ticksOnEntry;
                        finish(true, bossTicks, ticks.get().getRight());
                    } else {
                        finish(true);
                    }
                } catch (Exception e) {
                    log.warn("Could not parse timestamp from colosseum end message: {}", stripped);
                    finish(true);
                }
            }
        } else {
            Matcher matcher = waveEndRegex.matcher(stripped);
            if (matcher.find()) {
                try {
                    String inGameTime = matcher.group(1);
                    finish(inGameTime);
                } catch (Exception e) {
                    log.warn("Could not parse timestamp from wave end message: {}", stripped);
                    finish(true);
                }
            }
        }
    }

    private void dispatchGrapple(SolGrappleEvent.Outcome outcome) {
        if (pendingGrappleTarget == null) {
            return;
        }

        Player player = client.getLocalPlayer();
        WorldPoint coords = player != null ? getWorldLocation(player) : null;
        dispatchEvent(new SolGrappleEvent(getTick(), coords, pendingGrappleTick, pendingGrappleTarget, outcome));
        pendingGrappleTarget = null;
        pendingGrappleTick = -1;
    }

    private void startWave(int tickOffset) {
        if (getState() == State.NOT_STARTED) {
            super.start(tickOffset);
            dispatchEvent(new HandicapChoiceEvent(
                    getStage(), handicap, Arrays.copyOf(handicapOptions, handicapOptions.length)));
            collectExistingReentryPools();
        }
    }

    private void collectExistingReentryPools() {
        Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
        if (tiles.length == 0 || tiles[0].length == 0) {
            return;
        }

        try {
            for (Tile[] tileRow : tiles[0]) {
                for (Tile tile : tileRow) {
                    if (tile == null) {
                        continue;
                    }
                    if (tile.getGameObjects() != null) {
                        for (GameObject gameObject : tile.getGameObjects()) {
                            if (gameObject != null && gameObject.getId() == REENTRY_PRIMARY_GAME_OBJECT_ID) {
                                reentryPrimaryPoolsSpawned.add(gameObject);
                            }
                        }
                    }
                    GroundObject groundObject = tile.getGroundObject();
                    if (groundObject != null && groundObject.getId() == REENTRY_SECONDARY_GROUND_OBJECT_ID) {
                        reentrySecondaryPoolsSpawned.add(groundObject);
                    }
                }
            }
        } catch (Exception e) {
            log.warn("Error collecting existing reentry pools on wave start", e);
        }
    }

    private void sendReentryPoolsEvent() {
        if (reentryPrimaryPoolsSpawned.isEmpty()
                && reentrySecondaryPoolsSpawned.isEmpty()
                && reentryPrimaryPoolsDespawned.isEmpty()
                && reentrySecondaryPoolsDespawned.isEmpty()) {
            return;
        }

        List<WorldPoint> primarySpawned =
                reentryPrimaryPoolsSpawned.stream().map(this::getWorldLocation).collect(Collectors.toList());
        List<WorldPoint> secondarySpawned = reentrySecondaryPoolsSpawned.stream()
                .map(this::getWorldLocation)
                .collect(Collectors.toList());
        List<WorldPoint> primaryDespawned = reentryPrimaryPoolsDespawned.stream()
                .map(this::getWorldLocation)
                .collect(Collectors.toList());
        List<WorldPoint> secondaryDespawned = reentrySecondaryPoolsDespawned.stream()
                .map(this::getWorldLocation)
                .collect(Collectors.toList());

        dispatchEvent(new ReentryPoolsEvent(
                getStage(), getTick(), primarySpawned, secondarySpawned, primaryDespawned, secondaryDespawned));
    }

    private void handleSolEvents() {
        // If a grapple was announced and no defend/parry message arrived within 4 ticks, it was a hit.
        if (pendingGrappleTarget != null && getTick() - pendingGrappleTick > 4) {
            dispatchGrapple(SolGrappleEvent.Outcome.HIT);
        }

        NPC sol = getTrackedNpcs().stream()
                .filter(trackedNpc ->
                        ColosseumNpc.isSolHeredit(trackedNpc.getNpc().getId()))
                .findFirst()
                .map(TrackedNpc::getNpc)
                .orElse(null);
        if (sol == null) {
            return;
        }

        if (!solDustGraphics.isEmpty()) {
            SolDustEvent.Pattern pattern;
            SolDustEvent.Direction direction = null;

            WorldPoint solLoc = getWorldLocation(sol);
            int solSize = sol.getWorldArea().getWidth();
            WorldArea solArea = new WorldArea(solLoc.getX(), solLoc.getY(), solSize, solSize, solLoc.getPlane());

            // Pattern can be identified by counting how many dusts are 2 tiles away from Sol.
            List<WorldPoint> twoAway = solDustGraphics.stream()
                    .filter(point -> solArea.distanceTo2D(point) == 2)
                    .collect(Collectors.toList());

            switch (twoAway.size()) {
                case 0:
                    // Safe ring 2 tiles away => shield 1.
                    pattern = SolDustEvent.Pattern.SHIELD_1;
                    break;
                case 2:
                    // Two trident prongs => trident 1.
                    pattern = SolDustEvent.Pattern.TRIDENT_1;
                    break;
                case 3:
                    // Three trident prongs => trident 2.
                    pattern = SolDustEvent.Pattern.TRIDENT_2;
                    break;
                default:
                    // Safe ring 3 tiles away, everything else is dust => shield 2.
                    pattern = SolDustEvent.Pattern.SHIELD_2;
                    break;
            }

            if (pattern == SolDustEvent.Pattern.TRIDENT_1 || pattern == SolDustEvent.Pattern.TRIDENT_2) {
                WorldPoint dust = twoAway.get(0);

                if (dust.getX() < solLoc.getX()) {
                    direction = SolDustEvent.Direction.WEST;
                } else if (dust.getX() >= solLoc.getX() + solSize) {
                    direction = SolDustEvent.Direction.EAST;
                } else if (dust.getY() >= solLoc.getY() + solSize) {
                    direction = SolDustEvent.Direction.NORTH;
                } else {
                    direction = SolDustEvent.Direction.SOUTH;
                }
            }

            dispatchEvent(new SolDustEvent(getTick(), getWorldLocation(sol), pattern, direction));
        }

        if (!solPools.isEmpty()) {
            dispatchEvent(new SolPoolsEvent(getTick(), solPools));
        }

        if (solLaserGraphic != null) {
            SolLasersEvent.Phase phase = SOL_LASER_SCAN_GRAPHIC_OBJECT_IDS.contains(solLaserGraphic.getId())
                    ? SolLasersEvent.Phase.SCAN
                    : SolLasersEvent.Phase.SHOT;
            dispatchEvent(new SolLasersEvent(getTick(), phase));
        }
    }
}

package io.blert.challenges.inferno;

import io.blert.core.*;
import io.blert.events.ChallengeEndEvent;
import io.blert.events.ChallengeStartEvent;
import io.blert.util.ChatText;
import io.blert.util.DeferredTask;
import io.blert.util.Location;
import io.blert.util.Tick;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import org.apache.commons.lang3.tuple.Pair;

@Slf4j
public class InfernoChallenge extends RecordableChallenge {
    private static final int INFERNO_REGION_ID = 9043;
    private static final int MOR_UL_REK_SOUTHWEST_REGION_ID = 9807;
    private static final int MOR_UL_REK_NORTHWEST_REGION_ID = 9808;
    private static final int MOR_UL_REK_SOUTHEAST_REGION_ID = 10063;
    private static final int MOR_UL_REK_NORTHEAST_REGION_ID = 10064;

    private static final String WAVE_1_START_MESSAGE = "Wave: 1";
    static final Pattern INFERNO_END_REGEX = Pattern.compile("Duration: (" + Tick.TIME_STRING_REGEX + ")");
    // The inferno timer begins 6 seconds (10 ticks) before the first wave.
    private static final int WAVE_1_TIME_OFFSET_TICKS = 10;

    private int wave;
    private int challengeStartTick;
    private int reportedChallengeTicks;

    private @Nullable DeferredTask deferredTask = null;

    private boolean hasLogged;

    private WaveDataTracker waveDataTracker;
    private Pillar westPillar;
    private Pillar eastPillar;
    private Pillar southPillar;

    public InfernoChallenge(Client client, ClientThread clientThread) {
        super(Challenge.INFERNO, client, clientThread);
        this.wave = 0;
        this.challengeStartTick = -1;
        this.reportedChallengeTicks = -1;
        this.hasLogged = false;
    }

    @Nullable
    @Override
    protected DataTracker getActiveTracker() {
        return waveDataTracker;
    }

    public int recordedDurationTicks() {
        if (getState().isInactive() || challengeStartTick == -1) {
            return 0;
        }
        int currentTick = client.getTickCount();
        return currentTick - challengeStartTick;
    }

    public boolean hasLogged() {
        return hasLogged;
    }

    @Override
    public boolean containsLocation(WorldPoint worldPoint) {
        return worldPoint.getRegionID() == INFERNO_REGION_ID
                || worldPoint.getRegionID() == MOR_UL_REK_SOUTHWEST_REGION_ID
                || worldPoint.getRegionID() == MOR_UL_REK_NORTHWEST_REGION_ID
                || worldPoint.getRegionID() == MOR_UL_REK_SOUTHEAST_REGION_ID
                || worldPoint.getRegionID() == MOR_UL_REK_NORTHEAST_REGION_ID;
    }

    @Override
    protected void onInitialize() {
        reset();
        addRaider(new Raider(client.getLocalPlayer(), true));
    }

    @Override
    protected void onTerminate() {
        if (getState().inChallenge()) {
            log.warn("Terminating Inferno challenge while still active");
            finishInferno(ChallengeState.INACTIVE);
        }
        cleanup();
    }

    @Override
    protected void onTick() {
        if (deferredTask != null) {
            deferredTask.tick();
        } else {
            // The deferred task is used for state changes, so only check state
            // manually if it's not pending.
            updateChallengeState();
        }

        if (getState().isInactive()) {
            return;
        }

        if (waveDataTracker != null) {
            waveDataTracker.tick();

            if (waveDataTracker.completed() && wave < 69) {
                prepareNextWave();
            }
        }
    }

    @Nullable
    @Override
    protected Stage getStage() {
        return waveDataTracker != null ? waveDataTracker.getStage() : null;
    }

    @Override
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN && getState().inChallenge()) {
            hasLogged = true;
        }
        super.onGameStateChanged(event);
    }

    @Override
    public void onChatMessage(ChatMessage event) {
        if (!getState().isInactive() && event.getType() == ChatMessageType.GAMEMESSAGE) {
            String stripped = ChatText.stripFormatting(event.getMessage());
            if (stripped.equals(WAVE_1_START_MESSAGE)) {
                challengeStartTick = client.getTickCount() - WAVE_1_TIME_OFFSET_TICKS;
            } else {
                Matcher matcher = INFERNO_END_REGEX.matcher(stripped);
                if (matcher.find()) {
                    try {
                        reportedChallengeTicks = Tick.fromTimeString(matcher.group(1))
                                .map(Pair::getLeft)
                                .orElse(-1);
                    } catch (Exception e) {
                        reportedChallengeTicks = -1;
                    }
                    deferredTask = new DeferredTask(() -> finishInferno(ChallengeState.COMPLETE), 3);
                }
            }
        }
        super.onChatMessage(event);
    }

    @Override
    public void onNpcSpawned(NpcSpawned event) {
        NPC npc = event.getNpc();
        if (npc.getId() == InfernoNpc.ROCKY_SUPPORT.getId()) {
            Pillar pillar = new Pillar(npc, npc.getIndex(), Location.getWorldLocation(client, npc.getWorldLocation()));
            switch (pillar.getLocation()) {
                case WEST:
                    westPillar = pillar;
                    break;
                case EAST:
                    eastPillar = pillar;
                    break;
                case SOUTH:
                    southPillar = pillar;
                    break;
            }
        }
        super.onNpcSpawned(event);
    }

    public void removePillar(TrackedNpc pillar) {
        if (!(pillar instanceof Pillar)) {
            return;
        }

        if (pillar == westPillar) {
            westPillar = null;
        } else if (pillar == eastPillar) {
            eastPillar = null;
        } else if (pillar == southPillar) {
            southPillar = null;
        }
    }

    private void updateChallengeState() {
        WorldPoint playerLocation =
                Location.getWorldLocation(client, client.getLocalPlayer().getWorldLocation());
        if (playerLocation == null) {
            return;
        }

        boolean inInferno = playerLocation.getRegionID() == INFERNO_REGION_ID;

        if (getState().isInactive()) {
            if (inInferno) {
                startInferno();
            }
        } else if (!inInferno) {
            if (getState() == ChallengeState.COMPLETE) {
                setState(ChallengeState.INACTIVE);
            } else {
                finishInferno(ChallengeState.INACTIVE);
            }
        }
    }

    private void startInferno() {
        log.info("Starting Inferno challenge");
        setState(ChallengeState.ACTIVE);
        reportedChallengeTicks = -1;

        // TODO(frolv): What happens if someone turns on their plugin mid-challenge?
        Stage stage = Stage.INFERNO_WAVE_1;

        List<String> usernames = getParty().stream().map(Raider::getUsername).collect(Collectors.toList());
        dispatchEvent(new ChallengeStartEvent(getChallenge(), ChallengeMode.NO_MODE, stage, usernames, false));

        prepareNextWave();
    }

    private void finishInferno(ChallengeState state) {
        log.info("Finishing Inferno challenge with state: {}", state);
        int reported = reportedChallengeTicks;
        cleanup();
        dispatchEvent(new ChallengeEndEvent(reported, reported));
        setState(state);
    }

    private void prepareNextWave() {
        clearWaveDataTracker();

        wave++;
        waveDataTracker = new WaveDataTracker(this, client, wave);

        if (westPillar != null) {
            waveDataTracker.addTrackedNpc(westPillar);
        }
        if (eastPillar != null) {
            waveDataTracker.addTrackedNpc(eastPillar);
        }
        if (southPillar != null) {
            waveDataTracker.addTrackedNpc(southPillar);
        }
    }

    private void clearWaveDataTracker() {
        if (waveDataTracker != null) {
            waveDataTracker.terminate();
            waveDataTracker = null;
        }
    }

    private void cleanup() {
        clearWaveDataTracker();
        reset();
    }

    private void reset() {
        deferredTask = null;
        wave = 0;
        challengeStartTick = -1;
        reportedChallengeTicks = -1;
        hasLogged = false;
        westPillar = null;
        eastPillar = null;
        southPillar = null;
    }
}

package io.blert.challenges.inferno;

import io.blert.core.Hitpoints;
import io.blert.core.NpcAttack;
import java.util.Optional;
import lombok.Getter;
import org.apache.commons.lang3.tuple.Pair;

public enum InfernoNpc {
    NIBBLER(7691, 10),
    BAT(7692, 25, Pair.of(7578, NpcAttack.INFERNO_BAT_AUTO)),
    BLOB(
            7693,
            40,
            Pair.of(7581, NpcAttack.INFERNO_BLOB_MAGE),
            Pair.of(7582, NpcAttack.INFERNO_BLOB_MELEE),
            Pair.of(7583, NpcAttack.INFERNO_BLOB_RANGED)),
    BLOB_MAGER(7694, 15, Pair.of(7581, NpcAttack.INFERNO_BLOBLET_MAGE_AUTO)),
    BLOB_RANGER(7695, 15, Pair.of(7583, NpcAttack.INFERNO_BLOBLET_RANGED_AUTO)),
    BLOB_MELEER(7696, 15, Pair.of(7582, NpcAttack.INFERNO_BLOBLET_MELEE_AUTO)),
    MELEER(7697, 75, Pair.of(7597, NpcAttack.INFERNO_MELEER_AUTO), Pair.of(7600, NpcAttack.INFERNO_MELEER_DIG)),
    RANGER(7698, 125, Pair.of(7604, NpcAttack.INFERNO_RANGER_MELEE), Pair.of(7605, NpcAttack.INFERNO_RANGER_AUTO)),
    MAGER(
            7699,
            220,
            Pair.of(7610, NpcAttack.INFERNO_MAGER_AUTO),
            Pair.of(7611, NpcAttack.INFERNO_MAGER_RESURRECT),
            Pair.of(7612, NpcAttack.INFERNO_MAGER_MELEE)),
    JAD(
            7700,
            350,
            Pair.of(7590, NpcAttack.INFERNO_JAD_MELEE),
            Pair.of(7592, NpcAttack.INFERNO_JAD_MAGE),
            Pair.of(7593, NpcAttack.INFERNO_JAD_RANGED)),
    JAD_HEALER(7701, 90, Pair.of(2637, NpcAttack.INFERNO_JAD_HEALER_AUTO)),
    ZUK_RANGER(7702, 125, Pair.of(7604, NpcAttack.INFERNO_RANGER_MELEE), Pair.of(7605, NpcAttack.INFERNO_RANGER_AUTO)),
    ZUK_MAGER(
            7703,
            220,
            Pair.of(7610, NpcAttack.INFERNO_MAGER_AUTO),
            Pair.of(7611, NpcAttack.INFERNO_MAGER_RESURRECT),
            Pair.of(7612, NpcAttack.INFERNO_MAGER_MELEE)),
    ZUK_JAD(
            7704,
            350,
            Pair.of(7590, NpcAttack.INFERNO_JAD_MELEE),
            Pair.of(7592, NpcAttack.INFERNO_JAD_MAGE),
            Pair.of(7593, NpcAttack.INFERNO_JAD_RANGED)),
    ZUK_JAD_HEALER(7705, 90, Pair.of(2637, NpcAttack.INFERNO_JAD_HEALER_AUTO)),
    ZUK(7706, 1200, Pair.of(7566, NpcAttack.INFERNO_ZUK_AUTO)),
    ZUK_MOVING_SAFESPOT(7707, 600),
    ZUK_HEALER(7708, 75),
    ROCKY_SUPPORT(7709, 255),
    ;

    @Getter
    private final int id;

    @Getter
    private final int hitpoints;

    private final Pair<Integer, NpcAttack>[] attacks;

    public static Optional<InfernoNpc> withId(int id) {
        for (InfernoNpc npc : values()) {
            if (npc.id == id) {
                return Optional.of(npc);
            }
        }
        return Optional.empty();
    }

    Optional<NpcAttack> getAttack(int animationId) {
        for (Pair<Integer, NpcAttack> attack : attacks) {
            if (attack.getLeft() == animationId) {
                return Optional.of(attack.getRight());
            }
        }
        return Optional.empty();
    }

    boolean isPillar() {
        return this == ROCKY_SUPPORT;
    }

    boolean isResurrectable() {
        switch (this) {
            case BAT:
            case BLOB:
            case MELEER:
            case RANGER:
            case MAGER:
                return true;
            default:
                return false;
        }
    }

    Hitpoints resurrectedHitpoints() {
        return new Hitpoints((hitpoints + 1) / 2, hitpoints);
    }

    @SafeVarargs
    InfernoNpc(int id, int hitpoints, Pair<Integer, NpcAttack>... attacks) {
        this.id = id;
        this.hitpoints = hitpoints;
        this.attacks = attacks;
    }
}

package io.blert.challenges.inferno;

import io.blert.core.BasicTrackedNpc;
import io.blert.core.Hitpoints;
import lombok.Getter;
import lombok.NonNull;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

@Getter
public class Pillar extends BasicTrackedNpc {
    enum Location {
        WEST,
        EAST,
        SOUTH,
    }

    private final Location location;

    private final WorldPoint WEST_PILLAR_LOCATION = new WorldPoint(2257, 5349, 0);
    private final WorldPoint EAST_PILLAR_LOCATION = new WorldPoint(2274, 5351, 0);
    private final WorldPoint SOUTH_PILLAR_LOCATION = new WorldPoint(2267, 5335, 0);

    public Pillar(@NonNull NPC npc, long roomId, WorldPoint point) {
        super(npc, roomId, new Hitpoints(InfernoNpc.ROCKY_SUPPORT.getHitpoints()));
        if (point.equals(WEST_PILLAR_LOCATION)) {
            this.location = Location.WEST;
        } else if (point.equals(EAST_PILLAR_LOCATION)) {
            this.location = Location.EAST;
        } else {
            this.location = Location.SOUTH;
        }
    }
}

package io.blert.challenges.inferno;

import io.blert.core.*;
import io.blert.events.NpcAttackEvent;
import io.blert.events.inferno.InfernoWaveStartEvent;
import io.blert.util.ChatText;
import java.util.Optional;
import java.util.regex.Matcher;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;

@Slf4j
public class WaveDataTracker extends DataTracker {
    private static final String waveEndMessage = "Wave completed!";
    private final int wave;
    private final String waveStartMessage;

    public static Stage waveToStage(int wave) {
        if (wave < 1 || wave > 69) {
            throw new IllegalArgumentException("Wave must be between 1 and 69");
        }
        return Stage.values()[Stage.INFERNO_WAVE_1.ordinal() + (wave - 1)];
    }

    public WaveDataTracker(InfernoChallenge challenge, Client client, int wave) {
        super(challenge, client, waveToStage(wave));
        this.wave = wave;
        this.waveStartMessage = String.format("Wave: %d", wave);
    }

    @Override
    protected void start() {
        super.start();

        InfernoChallenge challenge = (InfernoChallenge) getChallenge();
        if (!challenge.hasLogged()) {
            int startTick = challenge.recordedDurationTicks();
            dispatchEvent(new InfernoWaveStartEvent(getStage(), wave, startTick));
        }

        // NPC spawn events are typically received before the wave start message,
        // so capture any NPCs that are already present, ignoring those already
        // captured during NOT_STARTED.
        client.getTopLevelWorldView().npcs().stream()
                .filter(npc -> getTrackedNpcs().getByNpc(npc).isEmpty())
                .forEach(npc -> {
                    InfernoNpc.withId(npc.getId())
                            .filter(inf -> !inf.isPillar())
                            .ifPresent(infernoNpc -> addTrackedNpc(new BasicTrackedNpc(
                                    npc, generateRoomId(npc), new Hitpoints(infernoNpc.getHitpoints()))));
                });
    }

    @Override
    protected void onTick() {}

    @Override
    protected Optional<? extends TrackedNpc> onNpcSpawn(NpcSpawned event) {
        return InfernoNpc.withId(event.getNpc().getId()).flatMap(npc -> {
            if (npc.isPillar()) {
                // Pillars are managed by the challenge itself.
                return Optional.empty();
            }

            Hitpoints hitpoints = getTick() > 0 && wave <= 66 && npc.isResurrectable()
                    ? npc.resurrectedHitpoints()
                    : new Hitpoints(npc.getHitpoints());

            return Optional.of(new BasicTrackedNpc(event.getNpc(), generateRoomId(event.getNpc()), hitpoints));
        });
    }

    @Override
    protected boolean onNpcDespawn(NpcDespawned event, @Nullable TrackedNpc trackedNpc) {
        if (trackedNpc instanceof Pillar) {
            ((InfernoChallenge) getChallenge()).removePillar(trackedNpc);
            return true;
        }
        return trackedNpc != null;
    }

    @Override
    protected void onAnimation(AnimationChanged event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC)) {
            return;
        }

        Optional<InfernoNpc> maybeInfernoNpc = InfernoNpc.withId(((NPC) actor).getId());
        if (maybeInfernoNpc.isEmpty()) {
            return;
        }

        Optional<TrackedNpc> maybeNpc = getTrackedNpcs().getByNpc((NPC) actor);
        if (maybeNpc.isEmpty()) {
            return;
        }

        InfernoNpc infernoNpc = maybeInfernoNpc.get();
        TrackedNpc trackedNpc = maybeNpc.get();
        int animation = actor.getAnimation();

        infernoNpc
                .getAttack(animation)
                .ifPresent(npcAttack -> dispatchEvent(new NpcAttackEvent(
                        getStage(), getTick(), getWorldLocation(trackedNpc), npcAttack, trackedNpc)));
    }

    @Override
    protected void onMessage(ChatMessage event) {
        String stripped = ChatText.stripFormatting(event.getMessage());
        if (stripped.equals(waveStartMessage)) {
            start();
        } else if (stripped.equals(waveEndMessage)) {
            finish(true);
        } else {
            Matcher matcher = InfernoChallenge.INFERNO_END_REGEX.matcher(stripped);
            if (matcher.find()) {
                finish(true);
            }
        }
    }
}

package io.blert.challenges.mokhaiotl;

import com.google.common.collect.ImmutableSet;
import io.blert.core.*;
import io.blert.events.NpcAttackEvent;
import io.blert.events.mokhaiotl.*;
import io.blert.util.ChatText;
import io.blert.util.Location;
import io.blert.util.Tick;
import java.util.*;
import java.util.function.BiFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;

@Slf4j
public class DelveDataTracker extends DataTracker {
    private static final int MOKHAIOTL_AUTO_ANIMATION_ID = 12406;
    private static final int MOKHAIOTL_BALL_ANIMATION_ID = 12407;
    private static final int MOKHAIOTL_CHARGE_ANIMATION_ID = 12409;
    private static final int MOKHAIOTL_BLAST_ANIMATION_ID = 12411;
    private static final int MOKHAIOTL_MELEE_ANIMATION_ID = 12416;
    private static final int MOKHAIOTL_RACECAR_ANIMATION_ID = 12417;

    private static final int MOKHAIOTL_RANGED_BALL_PROJECTILE_ID = 3384;
    private static final int MOKHAIOTL_MAGE_BALL_PROJECTILE_ID = 3385;

    private static final int ACID_BLOOD_GAME_OBJECT_ID = 57283;
    private static final int ROCK_GAME_OBJECT_ID = 57286;

    private static final Set<Number> SHOCKWAVE_GRAPHICS_IDs = ImmutableSet.of(3405, 3406, 3407);

    private static final int[] HITPOINTS_BY_DELVE = new int[] {
        -1, // 1-indexed
        525, // Delve 1
        550, // Delve 2
        575, // Delve 3
        600, // Delve 4
        625, // Delve 5
        650, // Delve 6
        650, // Delve 7
        675, // Delve 8+
    };
    private static final int SHIELD_HITPOINTS = 500;

    private enum PhaseChange {
        NONE,
        SHIELD_START,
        SHIELD_END,
    }

    private final Pattern delveEndRegex;
    private final int delve;

    private BasicTrackedNpc mokhaiotl = null;
    PhaseChange phaseChange;
    private int hitpointsBeforeShield;
    private int unidentifiedAttackTick;
    private int lastRacecarTick;
    private final Map<Projectile, Orb> activeOrbs = new HashMap<>();
    private final Set<GameObject> activeRocksAndSplats = new HashSet<>();
    private final List<GameObject> rocksAndSplatsSpawnedThisTick = new ArrayList<>();
    private final List<GameObject> rocksAndSplatsDespawnedThisTick = new ArrayList<>();
    private final Set<WorldPoint> shockwaveLocationsThisTick = new HashSet<>();
    private final Queue<Hitsplat> healsThisTick = new LinkedList<>();
    private final Queue<TrackedNpc> larvaeLeakedThisTick = new LinkedList<>();

    public static Stage delveToStage(int delve) {
        if (delve > 8) {
            return Stage.MOKHAIOTL_DELVE_8PLUS;
        }
        return Stage.values()[Stage.MOKHAIOTL_DELVE_1.ordinal() + delve - 1];
    }

    public DelveDataTracker(RecordableChallenge challenge, Client client, int delve) {
        super(challenge, client, delveToStage(delve));
        this.delve = delve;
        if (delve > 8) {
            this.delveEndRegex =
                    Pattern.compile("Delve level: 8\\+ \\(" + delve + "\\) duration: (" + Tick.TIME_STRING_REGEX + ")");
        } else {
            this.delveEndRegex =
                    Pattern.compile("Delve level: " + delve + " duration: (" + Tick.TIME_STRING_REGEX + ")");
        }
        this.unidentifiedAttackTick = -1;
        this.lastRacecarTick = -1;
        this.phaseChange = PhaseChange.NONE;
    }

    protected void start() {
        super.start();
        log.info("Starting delve {}", delve);

        // The client doesn't receive `GameObjectSpawned` events for acid already present
        // when entering the delve, so we have to manually grab our initial set.
        Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
        if (tiles.length == 0 || tiles[0].length == 0) {
            log.warn("No tiles available during delve start, cannot initialize splats");
            return;
        }

        try {
            for (Tile[] tileRow : tiles[0]) {
                for (Tile tile : tileRow) {
                    if (tile == null || tile.getGameObjects() == null) {
                        continue;
                    }
                    for (GameObject gameObject : tile.getGameObjects()) {
                        if (gameObject != null && gameObject.getId() == ACID_BLOOD_GAME_OBJECT_ID) {
                            activeRocksAndSplats.add(gameObject);
                            rocksAndSplatsSpawnedThisTick.add(gameObject);
                        }
                    }
                }
            }
            log.debug("Found {} splats on delve start", activeRocksAndSplats.size());
        } catch (Exception e) {
            log.warn("Error while initializing splats on delve start", e);
        }
    }

    @Override
    protected void onTick() {
        final int tick = getTick();

        checkForNewOrbs(tick);

        if (phaseChange == PhaseChange.SHIELD_START) {
            hitpointsBeforeShield = mokhaiotl.getHitpoints().getCurrent();
            mokhaiotl.setHitpoints(new Hitpoints(SHIELD_HITPOINTS));
        } else if (phaseChange == PhaseChange.SHIELD_END) {
            mokhaiotl.setHitpoints(new Hitpoints(hitpointsBeforeShield, HITPOINTS_BY_DELVE[Math.min(delve, 8)]));
        }

        if (!rocksAndSplatsSpawnedThisTick.isEmpty() || !rocksAndSplatsDespawnedThisTick.isEmpty()) {
            BiFunction<List<GameObject>, Integer, List<WorldPoint>> toWorldPoints = (objects, id) -> objects.stream()
                    .filter(o -> o.getId() == id)
                    .map(this::getWorldLocation)
                    .collect(Collectors.toList());
            List<WorldPoint> rocksSpawned = toWorldPoints.apply(rocksAndSplatsSpawnedThisTick, ROCK_GAME_OBJECT_ID);
            List<WorldPoint> splatsSpawned =
                    toWorldPoints.apply(rocksAndSplatsSpawnedThisTick, ACID_BLOOD_GAME_OBJECT_ID);
            List<WorldPoint> rocksDespawned = toWorldPoints.apply(rocksAndSplatsDespawnedThisTick, ROCK_GAME_OBJECT_ID);
            List<WorldPoint> splatsDespawned =
                    toWorldPoints.apply(rocksAndSplatsDespawnedThisTick, ACID_BLOOD_GAME_OBJECT_ID);
            dispatchEvent(new MokhaiotlObjectsEvent(
                    getStage(), tick, rocksSpawned, rocksDespawned, splatsSpawned, splatsDespawned));
        }

        while (!healsThisTick.isEmpty()) {
            Hitsplat hitsplat = healsThisTick.remove();
            TrackedNpc larva = larvaeLeakedThisTick.poll();
            if (larva == null) {
                log.warn("Mokhaiotl healed for {} without corresponding larva leak", hitsplat.getAmount());
                break;
            }
            dispatchEvent(new MokhaiotlLarvaLeakEvent(getStage(), tick, larva.getRoomId(), hitsplat.getAmount()));
        }

        if (!shockwaveLocationsThisTick.isEmpty()) {
            boolean isSlam = mokhaiotl.getNpc().getId() == MokhaiotlNpc.MOKHAIOTL_BURROWED.getId()
                    || lastRacecarTick >= tick - 12;
            NpcAttack attack = isSlam ? NpcAttack.MOKHAIOTL_SLAM : NpcAttack.MOKHAIOTL_SHOCKWAVE;
            dispatchEvent(new NpcAttackEvent(getStage(), tick, getWorldLocation(mokhaiotl), attack, mokhaiotl));
            dispatchEvent(new MokhaiotlShockwaveEvent(getStage(), tick, new ArrayList<>(shockwaveLocationsThisTick)));
        }

        rocksAndSplatsSpawnedThisTick.clear();
        rocksAndSplatsDespawnedThisTick.clear();
        shockwaveLocationsThisTick.clear();
        healsThisTick.clear();
        larvaeLeakedThisTick.clear();
        phaseChange = PhaseChange.NONE;
    }

    @Override
    protected void onMessage(ChatMessage event) {
        String stripped = ChatText.stripFormatting(event.getMessage());
        Matcher matcher = delveEndRegex.matcher(stripped);

        if (matcher.find()) {
            try {
                String inGameTime = matcher.group(1);
                finish(inGameTime);
            } catch (Exception e) {
                log.warn("Could not parse timestamp from delve end message: {}", stripped);
                finish(true);
            }
        }
    }

    @Override
    protected Optional<? extends TrackedNpc> onNpcSpawn(NpcSpawned event) {
        NPC npc = event.getNpc();
        Optional<MokhaiotlNpc> maybeNpc = MokhaiotlNpc.withId(npc.getId());
        if (maybeNpc.isEmpty()) {
            return Optional.empty();
        }

        MokhaiotlNpc mokhaiotlNpc = maybeNpc.get();
        if (mokhaiotlNpc.isMokhaiotl()) {
            if (getState() == State.NOT_STARTED) {
                start();
            }

            if (mokhaiotl == null) {
                int hitpoints = HITPOINTS_BY_DELVE[Math.min(delve, 8)];
                mokhaiotl = new BasicTrackedNpc(npc, generateRoomId(npc), new Hitpoints(hitpoints));
            }
            return Optional.of(mokhaiotl);
        }

        return Optional.of(new BasicTrackedNpc(npc, generateRoomId(npc), new Hitpoints(mokhaiotlNpc.getHitpoints())));
    }

    @Override
    protected boolean onNpcDespawn(NpcDespawned event, @Nullable TrackedNpc trackedNpc) {
        if (trackedNpc == null) {
            return false;
        }

        Optional<MokhaiotlNpc> maybeNpc = MokhaiotlNpc.withId(event.getNpc().getId());
        if (maybeNpc.isEmpty()) {
            return false;
        }

        MokhaiotlNpc mokhaiotlNpc = maybeNpc.get();
        if (mokhaiotlNpc.isLarva() && mokhaiotl != null && mokhaiotl.getNpc() != null) {
            NPC larva = trackedNpc.getNpc();
            WorldPoint mokhaiotlSouthwest = getWorldLocation(mokhaiotl);
            int mokhaiotlSize = mokhaiotl.getNpc().getComposition().getSize();
            WorldPoint mokhaiotlCenter = new WorldPoint(
                    mokhaiotlSouthwest.getX() + mokhaiotlSize / 2,
                    mokhaiotlSouthwest.getY() + mokhaiotlSize / 2,
                    mokhaiotlSouthwest.getPlane());

            if (getWorldLocation(larva).equals(mokhaiotlCenter)) {
                larvaeLeakedThisTick.add(trackedNpc);
            }
        }

        return true;
    }

    @Override
    protected void onNpcChange(NpcChanged event) {
        Optional<MokhaiotlNpc> maybeBefore = MokhaiotlNpc.withId(event.getOld().getId());
        Optional<MokhaiotlNpc> maybeAfter = MokhaiotlNpc.withId(event.getNpc().getId());
        if (maybeBefore.isEmpty() || maybeAfter.isEmpty()) {
            return;
        }

        MokhaiotlNpc before = maybeBefore.get();
        MokhaiotlNpc after = maybeAfter.get();

        if (before == MokhaiotlNpc.MOKHAIOTL && after == MokhaiotlNpc.MOKHAIOTL_SHIELDED) {
            phaseChange = PhaseChange.SHIELD_START;
        } else if (before == MokhaiotlNpc.MOKHAIOTL_SHIELDED) {
            phaseChange = PhaseChange.SHIELD_END;
        }
    }

    @Override
    protected void onHitsplat(HitsplatApplied hitsplatApplied) {
        if (hitsplatApplied.getActor() != mokhaiotl.getNpc()) {
            return;
        }

        Hitsplat hitsplat = hitsplatApplied.getHitsplat();
        if (hitsplat.getHitsplatType() == HitsplatID.HEAL) {
            healsThisTick.add(hitsplat);
        }
    }

    @Override
    protected void onAnimation(AnimationChanged event) {
        if (event.getActor() != mokhaiotl.getNpc()) {
            return;
        }

        final int tick = getTick();
        NpcAttack attack;

        switch (event.getActor().getAnimation()) {
            case MOKHAIOTL_AUTO_ANIMATION_ID:
                attack = NpcAttack.MOKHAIOTL_AUTO;
                unidentifiedAttackTick = tick;
                break;
            case MOKHAIOTL_BALL_ANIMATION_ID:
                attack = NpcAttack.MOKHAIOTL_BALL;
                unidentifiedAttackTick = tick;
                break;
            case MOKHAIOTL_CHARGE_ANIMATION_ID:
                attack = NpcAttack.MOKHAIOTL_CHARGE;
                break;
            case MOKHAIOTL_MELEE_ANIMATION_ID:
                attack = NpcAttack.MOKHAIOTL_MELEE;
                break;
            case MOKHAIOTL_BLAST_ANIMATION_ID:
                attack = NpcAttack.MOKHAIOTL_BLAST;
                break;
            case MOKHAIOTL_RACECAR_ANIMATION_ID:
                if (lastRacecarTick > tick - 5) {
                    return;
                }
                attack = NpcAttack.MOKHAIOTL_RACECAR;
                lastRacecarTick = tick;
                break;
            default:
                log.debug("Unhandled Mokhaiotl animation: {}", event.getActor().getAnimation());
                return;
        }

        WorldPoint location = getWorldLocation(mokhaiotl);
        dispatchEvent(new NpcAttackEvent(getStage(), tick, location, attack, mokhaiotl));
    }

    @Override
    protected void onProjectile(ProjectileMoved event) {
        Projectile projectile = event.getProjectile();
        int elapsed = projectile.getEndCycle() - projectile.getStartCycle() - projectile.getRemainingCycles();

        MokhaiotlAttackStyleEvent.Style style;

        switch (projectile.getId()) {
            case Orb.MELEE_PROJECTILE_ID:
                style = MokhaiotlAttackStyleEvent.Style.MELEE;
                break;
            case Orb.RANGED_PROJECTILE_ID:
            case MOKHAIOTL_RANGED_BALL_PROJECTILE_ID:
                style = MokhaiotlAttackStyleEvent.Style.RANGED;
                break;
            case Orb.MAGE_PROJECTILE_ID:
            case MOKHAIOTL_MAGE_BALL_PROJECTILE_ID:
                style = MokhaiotlAttackStyleEvent.Style.MAGE;
                break;
            default:
                return;
        }

        if (elapsed == 0 && mokhaiotl != null && mokhaiotl.getNpc() != null) {
            boolean fromMokhaiotl = mokhaiotl.getNpc().getWorldArea().contains(projectile.getSourcePoint());

            if (fromMokhaiotl && unidentifiedAttackTick != -1) {
                dispatchEvent(new MokhaiotlAttackStyleEvent(getStage(), getTick(), style, unidentifiedAttackTick));
                unidentifiedAttackTick = -1;
            }
        } else if (projectile.getRemainingCycles() <= 3) {
            Orb orb = activeOrbs.get(projectile);
            if (orb != null && orb.isActive()) {
                orb.setLanded(getTick());
                WorldPoint sourcePoint = Location.getWorldLocation(client, projectile.getSourcePoint());
                dispatchEvent(new MokhaiotlOrbEvent(getStage(), orb.getLandedTick(), orb, sourcePoint));
            }
        }
    }

    @Override
    protected void onGameObjectSpawn(GameObjectSpawned event) {
        GameObject object = event.getGameObject();
        switch (object.getId()) {
            case ACID_BLOOD_GAME_OBJECT_ID:
            case ROCK_GAME_OBJECT_ID:
                if (activeRocksAndSplats.add(object)) {
                    rocksAndSplatsSpawnedThisTick.add(object);
                }
                break;
            default:
                break;
        }
    }

    @Override
    protected void onGameObjectDespawn(GameObjectDespawned event) {
        GameObject object = event.getGameObject();
        switch (object.getId()) {
            case ACID_BLOOD_GAME_OBJECT_ID:
            case ROCK_GAME_OBJECT_ID:
                if (activeRocksAndSplats.remove(object)) {
                    rocksAndSplatsDespawnedThisTick.add(object);
                }
                break;
            default:
                break;
        }
    }

    @Override
    protected void onGraphicsObjectCreation(GraphicsObjectCreated event) {
        GraphicsObject object = event.getGraphicsObject();
        if (SHOCKWAVE_GRAPHICS_IDs.contains(object.getId())) {
            WorldPoint wp = WorldPoint.fromLocal(client, object.getLocation());
            shockwaveLocationsThisTick.add(Location.getWorldLocation(client, wp));
        }
    }

    @Override
    protected boolean npcIgnoresCooldown(NPC npc) {
        return MokhaiotlNpc.withId(npc.getId())
                .map(m -> {
                    if (m.isLarva() || m == MokhaiotlNpc.VOLATILE_EARTH) {
                        return true;
                    }

                    if (m == MokhaiotlNpc.MOKHAIOTL && mokhaiotl != null && mokhaiotl.getNpc() == npc) {
                        // Charging regular (non-shielded) Mokhaiotl can be interrupted off cooldown.
                        return npc.getAnimation() == MOKHAIOTL_CHARGE_ANIMATION_ID;
                    }

                    return false;
                })
                .orElse(false);
    }

    void checkForNewOrbs(int tick) {
        if (mokhaiotl == null) {
            return;
        }

        for (Projectile projectile : client.getProjectiles()) {
            if (!Orb.isOrb(projectile.getId())) {
                continue;
            }

            if (!activeOrbs.containsKey(projectile)) {
                boolean fromMokhaiotl = mokhaiotl.getNpc().getWorldArea().contains(projectile.getSourcePoint());

                Orb.Source source = fromMokhaiotl ? Orb.Source.MOKHAIOTL : Orb.Source.BALL;
                activeOrbs.put(projectile, new Orb(projectile, source, tick));
            }
        }
    }
}

package io.blert.challenges.mokhaiotl;

import io.blert.core.*;
import io.blert.events.ChallengeEndEvent;
import io.blert.events.ChallengeStartEvent;
import io.blert.util.ChatText;
import io.blert.util.Location;
import io.blert.util.Tick;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import org.apache.commons.lang3.tuple.Pair;

@Slf4j
public class MokhaiotlChallenge extends RecordableChallenge {
    private static final Pattern MOKHAIOTL_END_REGEX =
            Pattern.compile("Delve level 1 - 8 duration: (" + Tick.TIME_STRING_REGEX + ")");

    private DelveDataTracker delveDataTracker;
    int delve;
    int recordedChallengeTicks;
    int reportedChallengeTicks;

    public MokhaiotlChallenge(Client client, ClientThread clientThread) {
        super(Challenge.MOKHAIOTL, client, clientThread);
        delveDataTracker = null;
        delve = 0;
        recordedChallengeTicks = 0;
        reportedChallengeTicks = -1;
    }

    @Nullable
    @Override
    protected DataTracker getActiveTracker() {
        return delveDataTracker;
    }

    @Override
    public boolean containsLocation(WorldPoint worldPoint) {
        return MokhaiotlLocation.fromWorldPoint(worldPoint) != MokhaiotlLocation.ELSEWHERE;
    }

    @Override
    protected void onInitialize() {
        reset();
        addRaider(new Raider(client.getLocalPlayer(), true));
    }

    @Override
    protected void onTerminate() {
        if (getState().inChallenge()) {
            log.warn("Terminating Mokhaiotl challenge while still active");
            finishMokhaiotl();
        }
        cleanup();
    }

    @Override
    protected void onTick() {
        updateChallengeState();
        if (getState().isInactive()) {
            return;
        }

        if (delveDataTracker != null) {
            delveDataTracker.tick();

            if (delveDataTracker.completed()) {
                prepareNextDelve();
            }
        }
    }

    @Nullable
    @Override
    protected Stage getStage() {
        return delveDataTracker != null ? delveDataTracker.getStage() : null;
    }

    @Override
    public void onChatMessage(ChatMessage event) {
        if (!getState().isInactive() && event.getType() == ChatMessageType.GAMEMESSAGE) {
            Matcher matcher =
                    MokhaiotlChallenge.MOKHAIOTL_END_REGEX.matcher(ChatText.stripFormatting(event.getMessage()));
            if (matcher.find()) {
                try {
                    reportedChallengeTicks = Tick.fromTimeString(matcher.group(1))
                            .map(Pair::getLeft)
                            .orElse(-1);
                } catch (Exception e) {
                    reportedChallengeTicks = -1;
                }
            }
        }
        super.onChatMessage(event);
    }

    void updateChallengeState() {
        WorldPoint playerLocation =
                Location.getWorldLocation(client, client.getLocalPlayer().getWorldLocation());
        if (playerLocation == null) {
            return;
        }

        MokhaiotlLocation location = MokhaiotlLocation.fromWorldPoint(playerLocation);

        if (getState().isInactive()) {
            if (location.inMokhaiotl()) {
                startMokhaiotl();
            }
        } else if (!location.inMokhaiotl()) {
            clearDelveDataTracker();
            finishMokhaiotl();
        }
    }

    private void startMokhaiotl() {
        log.info("Starting Mokhaiotl challenge");
        setState(ChallengeState.ACTIVE);
        reportedChallengeTicks = -1;

        // TODO(frolv): What happens if someone turns on their plugin mid-challenge?
        Stage stage = Stage.MOKHAIOTL_DELVE_1;

        List<String> usernames = getParty().stream().map(Raider::getUsername).collect(Collectors.toList());
        dispatchEvent(new ChallengeStartEvent(getChallenge(), ChallengeMode.NO_MODE, stage, usernames, false));

        // Immediately start delve 1.
        prepareNextDelve();
    }

    private void finishMokhaiotl() {
        log.info("Finishing Mokhaiotl challenge with state: {}", getState());

        int reported = reportedChallengeTicks;

        cleanup();
        dispatchEvent(new ChallengeEndEvent(reported, -1));
        setState(ChallengeState.INACTIVE);
    }

    void prepareNextDelve() {
        clearDelveDataTracker();

        delve++;
        if (delve > 8) {
            setState(ChallengeState.COMPLETE);
        }

        delveDataTracker = new DelveDataTracker(this, client, delve);
    }

    private void clearDelveDataTracker() {
        if (delveDataTracker != null) {
            delveDataTracker.terminate();
            delveDataTracker = null;
        }
    }

    private void cleanup() {
        clearDelveDataTracker();
        reset();
    }

    private void reset() {
        delve = 0;
        recordedChallengeTicks = 0;
        reportedChallengeTicks = -1;
    }
}

package io.blert.challenges.mokhaiotl;

import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

public enum MokhaiotlLocation {
    ELSEWHERE,
    CAVERN,
    LOBBY,
    DELVE_1,
    DELVE_MID,
    DELVE_DEEP;

    private static final int CAVERN_REGION_ID = 5268;
    private static final int DELVE_REGION_ID = 5269; // Delve 1 and lobby area
    private static final int DELVE_MID_REGION_ID = 13668; // Delves 2-5
    private static final int DELVE_DEEP_REGION_ID = 14180; // Delves 6+

    private static final WorldArea DELVE_1_AREA = new WorldArea(1299, 9559, 24, 26, 0);

    public static MokhaiotlLocation fromWorldPoint(WorldPoint point) {
        switch (point.getRegionID()) {
            case CAVERN_REGION_ID:
                return CAVERN;
            case DELVE_REGION_ID:
                return DELVE_1_AREA.contains(point) ? DELVE_1 : LOBBY;
            case DELVE_MID_REGION_ID:
                return DELVE_MID;
            case DELVE_DEEP_REGION_ID:
                return DELVE_DEEP;
            default:
                return ELSEWHERE;
        }
    }

    public boolean inMokhaiotl() {
        return this == DELVE_1 || this == DELVE_MID || this == DELVE_DEEP;
    }
}

