package io.blert.challenges.tob.rooms.verzik;

public enum VerzikSpecial {
    CRABS,
    WEBS,
    YELLOWS,
    BALL;

    public VerzikSpecial next() {
        switch (this) {
            case CRABS:
                return WEBS;
            case WEBS:
                return YELLOWS;
            case YELLOWS:
                return BALL;
            default:
                return CRABS;
        }
    }
}

