                stage,
                tick,
                point,
                attack,
                npc,
                npc.getNpc().getInteracting() instanceof Player
                        ? npc.getNpc().getInteracting().getName()
                        : null);
    }

    @Override
    protected String eventDataString() {
        return "npc_attack=(attack=" + attack + ", target=" + (target != null ? target : "none") + ")";
    }
}

