package io.blert.json;

import io.blert.challenges.colosseum.Handicap;
import io.blert.challenges.tob.rooms.maiden.MaidenCrab;
import io.blert.challenges.tob.rooms.nylocas.Nylo;
import io.blert.challenges.tob.rooms.sotetseg.Maze;
import io.blert.challenges.tob.rooms.verzik.VerzikCrab;
import io.blert.core.EquipmentSlot;
import io.blert.core.ItemDelta;
import io.blert.core.Stage;
import io.blert.core.TrackedNpc;
import io.blert.events.*;
import io.blert.events.colosseum.*;
import io.blert.events.inferno.InfernoWaveStartEvent;
import io.blert.events.mokhaiotl.*;
import io.blert.events.tob.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public class JsonEventTranslator {
    public static Event toJson(io.blert.events.Event event, @Nullable String challengeId) {
        Event json = new Event();
        json.type = event.getType().getId();
        json.tick = event.getTick();
        json.xCoord = event.getXCoord();
        json.yCoord = event.getYCoord();

        event.getStage().map(Stage::getId).ifPresent(s -> json.stage = s);

        if (challengeId != null) {
            json.challengeId = challengeId;
        }

        switch (event.getType()) {
            case CHALLENGE_START:
            case CHALLENGE_END:
            case CHALLENGE_UPDATE:
            case STAGE_UPDATE:
                throw new AssertionError(String.format("Event type %s has no JSON representation", event.getType()));

            case PLAYER_UPDATE: {
                PlayerUpdateEvent playerUpdateEvent = (PlayerUpdateEvent) event;

                int dataSource = playerUpdateEvent.getSource() == PlayerUpdateEvent.Source.PRIMARY
                        ? Event.Player.DATA_SOURCE_PRIMARY
                        : Event.Player.DATA_SOURCE_SECONDARY;

                Event.Player player = new Event.Player();
                player.dataSource = dataSource;
                player.name = playerUpdateEvent.getUsername();
                player.offCooldownTick = playerUpdateEvent.getOffCooldownTick();

                if (playerUpdateEvent.isSnapshot()) {
                    player.snapshot = true;
                }

                playerUpdateEvent.getHitpoints().ifPresent(sl -> player.hitpoints = sl.getValue());
                playerUpdateEvent.getPrayer().ifPresent(sl -> player.prayer = sl.getValue());
                playerUpdateEvent.getAttack().ifPresent(sl -> player.attack = sl.getValue());
                playerUpdateEvent.getStrength().ifPresent(sl -> player.strength = sl.getValue());
                playerUpdateEvent.getDefence().ifPresent(sl -> player.defence = sl.getValue());
                playerUpdateEvent.getRanged().ifPresent(sl -> player.ranged = sl.getValue());
                playerUpdateEvent.getMagic().ifPresent(sl -> player.magic = sl.getValue());

                playerUpdateEvent.getActivePrayers().ifPresent(prayers -> player.activePrayers = prayers.getValue());

                if (!playerUpdateEvent.getEquipmentChangesThisTick().isEmpty()) {
                    player.equipmentDeltas = playerUpdateEvent.getEquipmentChangesThisTick().stream()
                            .map(ItemDelta::getValue)
                            .collect(Collectors.toList());
                }

                json.player = player;
                break;
            }

            case PLAYER_ATTACK: {
                PlayerAttackEvent playerAttackEvent = (PlayerAttackEvent) event;
                Event.Attack attack = new Event.Attack();
                attack.type = playerAttackEvent.getAttack().getProtoId();
                attack.distanceToTarget = playerAttackEvent.getDistanceToTarget();

                playerAttackEvent.getWeapon().ifPresent(item -> {
                    attack.weapon = new Event.Player.EquippedItem();
                    attack.weapon.slot = EquipmentSlot.WEAPON.getId();
                    attack.weapon.id = item.getId();
                    attack.weapon.quantity = item.getQuantity();
                });

                if (playerAttackEvent.getTargetNpcId() != -1) {
                    attack.target = new Event.Npc();
                    attack.target.id = playerAttackEvent.getTargetNpcId();
                    attack.target.roomId = playerAttackEvent.getTargetRoomId();
                }

                json.playerAttack = attack;
                json.player = new Event.Player();
                json.player.name = playerAttackEvent.getUsername();
                break;
            }

            case PLAYER_SPELL: {
                PlayerSpellEvent playerSpellEvent = (PlayerSpellEvent) event;
                Event.Spell spell = new Event.Spell();
                spell.type = playerSpellEvent.getSpell().getId();

                if (playerSpellEvent.getTargetPlayer() != null) {
                    spell.targetPlayer = playerSpellEvent.getTargetPlayer();
                } else if (playerSpellEvent.hasNpcTarget()) {
                    spell.targetNpc = new Event.Npc();
                    spell.targetNpc.id = playerSpellEvent.getTargetNpcId();
                    spell.targetNpc.roomId = playerSpellEvent.getTargetNpcRoomId();
                }

                json.playerSpell = spell;
                json.player = new Event.Player();
                json.player.name = playerSpellEvent.getUsername();
                break;
            }

            case PLAYER_DEATH: {
                PlayerDeathEvent playerDeathEvent = (PlayerDeathEvent) event;
                json.player = new Event.Player();
                json.player.name = playerDeathEvent.getUsername();
                break;
            }

            case NPC_SPAWN:
            case NPC_UPDATE:
            case NPC_DEATH:
            case MAIDEN_CRAB_LEAK: {
                NpcEvent npcEvent = (NpcEvent) event;
                Event.Npc npc = new Event.Npc();
                npc.id = npcEvent.getNpcId();
                npc.roomId = npcEvent.getRoomId();
                npc.hitpoints = npcEvent.getHitpoints().getValue();
                npc.activePrayers = npcEvent.getPrayers();

                if (npcEvent.propertiesChanged()) {
                    addTranslatedNpcProperties(npc, npcEvent);
                }

                json.npc = npc;
                break;
            }

            case NPC_ATTACK: {
                NpcAttackEvent npcAttackEvent = (NpcAttackEvent) event;
                json.npc = new Event.Npc();
                json.npc.id = npcAttackEvent.getNpcId();
                json.npc.roomId = npcAttackEvent.getRoomId();

                Event.NpcAttack npcAttack = new Event.NpcAttack();
                npcAttack.attack = npcAttackEvent.getAttack().getId();
                if (npcAttackEvent.getTarget() != null) {
                    npcAttack.target = npcAttackEvent.getTarget();
                }
                json.npcAttack = npcAttack;
                break;
            }

            case MAIDEN_BLOOD_SPLATS: {
                MaidenBloodSplatsEvent bloodSplatsEvent = (MaidenBloodSplatsEvent) event;
                json.maidenBloodSplats = toCoordsList(bloodSplatsEvent.getBloodSplats());
                break;
            }

            case BLOAT_DOWN: {
                BloatDownEvent bloatDownEvent = (BloatDownEvent) event;
                json.bloatDown = new Event.BloatDown();
                json.bloatDown.downNumber = bloatDownEvent.getDownNumber();
                json.bloatDown.walkTime = bloatDownEvent.getUptime();
                break;
            }

            case BLOAT_HANDS_DROP:
            case BLOAT_HANDS_SPLAT: {
                BloatHandsEvent bloatHandsEvent = (BloatHandsEvent) event;
                json.bloatHands = toCoordsList(bloatHandsEvent.getHands());
                break;
            }

            case NYLO_WAVE_SPAWN:
            case NYLO_WAVE_STALL: {
                NyloWaveEvent nyloWaveEvent = (NyloWaveEvent) event;
                json.nyloWave = new Event.NyloWave();
                json.nyloWave.wave = nyloWaveEvent.getWave();
                json.nyloWave.nylosAlive = nyloWaveEvent.getNyloCount();
                json.nyloWave.roomCap = nyloWaveEvent.getNyloCap();
                break;
            }

            case SOTE_MAZE_PROC:
            case SOTE_MAZE_END: {
                SoteMazeEvent mazeEvent = (SoteMazeEvent) event;
                int maze = mazeEvent.getMaze() == Maze.MAZE_66 ? Event.SoteMaze.MAZE_66 : Event.SoteMaze.MAZE_33;
                json.soteMaze = new Event.SoteMaze();
                json.soteMaze.maze = maze;
                mazeEvent.getChosenPlayer().ifPresent(p -> json.soteMaze.chosenPlayer = p);
                break;
            }

            case SOTE_MAZE_PATH: {
                SoteMazePathEvent mazePathEvent = (SoteMazePathEvent) event;
                int maze = mazePathEvent.getMaze() == Maze.MAZE_66 ? Event.SoteMaze.MAZE_66 : Event.SoteMaze.MAZE_33;
                var coords = mazePathEvent
                        .mazeRelativePoints()
                        .map(JsonEventTranslator::worldPointToCoords)
                        .collect(Collectors.toList());

                json.soteMaze = new Event.SoteMaze();
                json.soteMaze.maze = maze;

                switch (mazePathEvent.getTileType()) {
                    case OVERWORLD_TILES:
                        json.soteMaze.overworldTiles = coords;
                        break;
                    case UNDERWORLD_PIVOTS:
                        json.soteMaze.underworldPivots = coords;
                        break;
                    case OVERWORLD_PIVOTS:
                        json.soteMaze.overworldPivots = coords;
                        break;
                }
                break;
            }

            case XARPUS_PHASE: {
                XarpusPhaseEvent xarpusPhaseEvent = (XarpusPhaseEvent) event;
                json.xarpusPhase = xarpusPhaseEvent.getPhase().ordinal();
                break;
            }

            case XARPUS_EXHUMED: {
                XarpusExhumedEvent xarpusExhumedEvent = (XarpusExhumedEvent) event;
                json.xarpusExhumed = new Event.XarpusExhumed();
                json.xarpusExhumed.spawnTick = xarpusExhumedEvent.getSpawnTick();
                json.xarpusExhumed.healAmount = xarpusExhumedEvent.getHealAmount();
                json.xarpusExhumed.healTicks = new ArrayList<>(xarpusExhumedEvent.getHealTicks());
                break;
            }

            case XARPUS_SPLAT: {
                XarpusSplatEvent xarpusSplatEvent = (XarpusSplatEvent) event;
                json.xarpusSplat = new Event.XarpusSplat();
                json.xarpusSplat.source = xarpusSplatEvent.getSource().getId();
                if (xarpusSplatEvent.getBounceFrom() != null) {
                    json.xarpusSplat.bounceFrom = worldPointToCoords(xarpusSplatEvent.getBounceFrom());
                }
                break;
            }

            case VERZIK_PHASE: {
                VerzikPhaseEvent verzikPhaseEvent = (VerzikPhaseEvent) event;
                json.verzikPhase = verzikPhaseEvent.getPhase().ordinal();
                break;
            }

            case VERZIK_DAWN: {
                VerzikDawnEvent verzikDawnEvent = (VerzikDawnEvent) event;
                json.verzikDawn = new Event.VerzikDawn();
                json.verzikDawn.attackTick = verzikDawnEvent.getAttackTick();
                json.verzikDawn.damage = verzikDawnEvent.getDamage();
                json.verzikDawn.player = verzikDawnEvent.getPlayer();
                break;
            }

            case VERZIK_BOUNCE: {
                VerzikBounceEvent verzikBounceEvent = (VerzikBounceEvent) event;
                json.verzikBounce = new Event.VerzikBounce();
                json.verzikBounce.npcAttackTick = verzikBounceEvent.getAttackTick();
                json.verzikBounce.playersInRange = verzikBounceEvent.getPlayersInRange();
                json.verzikBounce.playersNotInRange = verzikBounceEvent.getPlayersNotInRange();
                verzikBounceEvent.getBouncedPlayer().ifPresent(p -> json.verzikBounce.bouncedPlayer = p);
                break;
            }

            case VERZIK_YELLOWS: {
                VerzikYellowsEvent verzikYellowsEvent = (VerzikYellowsEvent) event;
                json.verzikYellows = toCoordsList(verzikYellowsEvent.getYellows());
                break;
            }

            case VERZIK_DAWN_DROP: {
                VerzikDawnDropEvent verzikDawnDropEvent = (VerzikDawnDropEvent) event;
                json.verzikDawnDrop = new Event.VerzikDawnDrop();
                json.verzikDawnDrop.dropped = verzikDawnDropEvent.isDropped();
                break;
            }

            case VERZIK_HEAL: {
                VerzikHealEvent verzikHealEvent = (VerzikHealEvent) event;
                json.verzikHeal = new Event.VerzikHeal();
                json.verzikHeal.player = verzikHealEvent.getPlayer();
                json.verzikHeal.healAmount = verzikHealEvent.getHealAmount();
                break;
            }

            case COLOSSEUM_HANDICAP_CHOICE: {
                HandicapChoiceEvent handicapChoiceEvent = (HandicapChoiceEvent) event;
                json.handicap = handicapChoiceEvent.getHandicap().getId();
                json.handicapOptions = Arrays.stream(handicapChoiceEvent.getHandicapOptions())
                        .map(Handicap::getId)
                        .collect(Collectors.toList());
                break;
            }

            case COLOSSEUM_TOTEM_HEAL: {
                TotemHealEvent totemHealEvent = (TotemHealEvent) event;
                json.colosseumTotemHeal = new Event.ColosseumTotemHeal();
                json.colosseumTotemHeal.source = new Event.Npc();
                json.colosseumTotemHeal.source.id = totemHealEvent.getSourceNpcId();
                json.colosseumTotemHeal.source.roomId = totemHealEvent.getSourceRoomId();
                json.colosseumTotemHeal.target = new Event.Npc();
                json.colosseumTotemHeal.target.id = totemHealEvent.getTargetNpcId();
                json.colosseumTotemHeal.target.roomId = totemHealEvent.getTargetRoomId();
                json.colosseumTotemHeal.startTick = totemHealEvent.getStartTick();
                json.colosseumTotemHeal.healAmount = totemHealEvent.getHealAmount();
                break;
            }

            case COLOSSEUM_REENTRY_POOLS: {
                ReentryPoolsEvent reentryPoolsEvent = (ReentryPoolsEvent) event;
                json.colosseumReentryPools = new Event.ColosseumReentryPools();
                json.colosseumReentryPools.primarySpawned = toCoordsList(reentryPoolsEvent.getPrimaryPoolsSpawned());
                json.colosseumReentryPools.primaryDespawned =
                        toCoordsList(reentryPoolsEvent.getPrimaryPoolsDespawned());
                json.colosseumReentryPools.secondarySpawned =
                        toCoordsList(reentryPoolsEvent.getSecondaryPoolsSpawned());
                json.colosseumReentryPools.secondaryDespawned =
                        toCoordsList(reentryPoolsEvent.getSecondaryPoolsDespawned());
                break;
            }

            case COLOSSEUM_SOL_DUST: {
                SolDustEvent solDustEvent = (SolDustEvent) event;
                json.colosseumSolDust = new Event.ColosseumSolDust();
                switch (solDustEvent.getPattern()) {
                    case TRIDENT_1:
                        json.colosseumSolDust.pattern = Event.ColosseumSolDust.PATTERN_TRIDENT_1;
                        break;
                    case TRIDENT_2:
                        json.colosseumSolDust.pattern = Event.ColosseumSolDust.PATTERN_TRIDENT_2;
                        break;
                    case SHIELD_1:
                        json.colosseumSolDust.pattern = Event.ColosseumSolDust.PATTERN_SHIELD_1;
                        break;
                    case SHIELD_2:
                        json.colosseumSolDust.pattern = Event.ColosseumSolDust.PATTERN_SHIELD_2;
                        break;
                }
                if (solDustEvent.getDirection() != null) {
                    switch (solDustEvent.getDirection()) {
                        case NORTH:
                            json.colosseumSolDust.direction = Event.ColosseumSolDust.DIRECTION_NORTH;
                            break;
                        case EAST:
                            json.colosseumSolDust.direction = Event.ColosseumSolDust.DIRECTION_EAST;
                            break;
                        case SOUTH:
                            json.colosseumSolDust.direction = Event.ColosseumSolDust.DIRECTION_SOUTH;
                            break;
                        case WEST:
                            json.colosseumSolDust.direction = Event.ColosseumSolDust.DIRECTION_WEST;
                            break;
                    }
                }
                break;
            }

            case COLOSSEUM_SOL_GRAPPLE: {
                SolGrappleEvent solGrappleEvent = (SolGrappleEvent) event;
                json.colosseumSolGrapple = new Event.ColosseumSolGrapple();
                json.colosseumSolGrapple.attackTick = solGrappleEvent.getAttackTick();
                json.colosseumSolGrapple.target = solGrappleEvent.getTarget().getId();
                switch (solGrappleEvent.getOutcome()) {
                    case HIT:
                        json.colosseumSolGrapple.outcome = Event.ColosseumSolGrapple.OUTCOME_HIT;
                        break;
                    case DEFEND:
                        json.colosseumSolGrapple.outcome = Event.ColosseumSolGrapple.OUTCOME_DEFEND;
                        break;
                    case PARRY:
                        json.colosseumSolGrapple.outcome = Event.ColosseumSolGrapple.OUTCOME_PARRY;
                        break;
                }
                break;
            }

            case COLOSSEUM_SOL_POOLS: {
                SolPoolsEvent solPoolsEvent = (SolPoolsEvent) event;
                json.colosseumSolPools = new Event.ColosseumSolPools();
                json.colosseumSolPools.pools = toCoordsList(solPoolsEvent.getPools());
                break;
            }

            case COLOSSEUM_SOL_LASERS: {
                SolLasersEvent solLasersEvent = (SolLasersEvent) event;
                json.colosseumSolLasers = new Event.ColosseumSolLasers();
                switch (solLasersEvent.getPhase()) {
                    case SCAN:
                        json.colosseumSolLasers.phase = Event.ColosseumSolLasers.PHASE_SCAN;
                        break;
                    case SHOT:
                        json.colosseumSolLasers.phase = Event.ColosseumSolLasers.PHASE_SHOT;
                        break;
                }
                break;
            }

            case MOKHAIOTL_ATTACK_STYLE: {
                MokhaiotlAttackStyleEvent mokhaiotlAttackStyleEvent = (MokhaiotlAttackStyleEvent) event;
                json.mokhaiotlAttackStyle = new Event.AttackStyle();
                json.mokhaiotlAttackStyle.style =
                        mokhaiotlAttackStyleEvent.getStyle().ordinal();
                json.mokhaiotlAttackStyle.npcAttackTick = mokhaiotlAttackStyleEvent.getAttackTick();
                break;
            }

            case MOKHAIOTL_ORB: {
                MokhaiotlOrbEvent mokhaiotlOrbEvent = (MokhaiotlOrbEvent) event;
                json.mokhaiotlOrb = new Event.MokhaiotlOrb();
                json.mokhaiotlOrb.source = mokhaiotlOrbEvent.getSource().getId();
                json.mokhaiotlOrb.sourcePoint = worldPointToCoords(mokhaiotlOrbEvent.getSourcePoint());
                json.mokhaiotlOrb.style = mokhaiotlOrbEvent.getStyle().getId();
                json.mokhaiotlOrb.startTick = mokhaiotlOrbEvent.getStartTick();
                json.mokhaiotlOrb.endTick = mokhaiotlOrbEvent.getEndTick();
                break;
            }

            case MOKHAIOTL_OBJECTS: {
                MokhaiotlObjectsEvent mokhaiotlObjectsEvent = (MokhaiotlObjectsEvent) event;
                json.mokhaiotlObjects = new Event.MokhaiotlObjects();
                json.mokhaiotlObjects.rocksSpawned = toCoordsList(mokhaiotlObjectsEvent.getRocksSpawned());
                json.mokhaiotlObjects.splatsDespawned = toCoordsList(mokhaiotlObjectsEvent.getSplatsDespawned());
                json.mokhaiotlObjects.rocksDespawned = toCoordsList(mokhaiotlObjectsEvent.getRocksDespawned());
                json.mokhaiotlObjects.splatsSpawned = toCoordsList(mokhaiotlObjectsEvent.getSplatsSpawned());
                break;
            }

            case MOKHAIOTL_LARVA_LEAK: {
                MokhaiotlLarvaLeakEvent mokhaiotlLarvaLeakEvent = (MokhaiotlLarvaLeakEvent) event;
                json.mokhaiotlLarvaLeak = new Event.MokhaiotlLarvaLeak();
                json.mokhaiotlLarvaLeak.roomId = mokhaiotlLarvaLeakEvent.getRoomId();
                json.mokhaiotlLarvaLeak.healAmount = mokhaiotlLarvaLeakEvent.getHealAmount();
                break;
            }

            case MOKHAIOTL_SHOCKWAVE: {
                MokhaiotlShockwaveEvent mokhaiotlShockwaveEvent = (MokhaiotlShockwaveEvent) event;
                json.mokhaiotlShockwave = new Event.MokhaiotlShockwave();
                json.mokhaiotlShockwave.tiles = toCoordsList(mokhaiotlShockwaveEvent.getShockwaveTiles());
                break;
            }

            case INFERNO_WAVE_START: {
                InfernoWaveStartEvent infernoWaveStartEvent = (InfernoWaveStartEvent) event;
                json.infernoWaveStart = new Event.InfernoWaveStart();
                json.infernoWaveStart.wave = infernoWaveStartEvent.getWave();
                json.infernoWaveStart.overallTicks = infernoWaveStartEvent.getStartTick();
                break;
            }

            default:
                break;
        }

        return json;
    }

    private static List<Coords> toCoordsList(List<WorldPoint> points) {
        return points.stream().map(JsonEventTranslator::worldPointToCoords).collect(Collectors.toList());
    }

    private static Coords worldPointToCoords(WorldPoint point) {
        return new Coords(point.getX(), point.getY());
    }

    /**
     * Adds tracked NPC-specific properties to the given {@link Event.Npc} based
     * on the {@link NpcEvent}.
     *
     * @param npc   Npc to which the properties should be added.
     * @param event Event describing the NPC.
     */
    private static void addTranslatedNpcProperties(Event.Npc npc, NpcEvent event) {
        TrackedNpc.Properties properties = event.getProperties();

        if (properties instanceof MaidenCrab.Properties) {
            var crab = (MaidenCrab.Properties) properties;
            npc.maidenCrab = new Event.MaidenCrab();
            npc.maidenCrab.spawn = crab.getSpawn().ordinal();
            npc.maidenCrab.position = crab.getPosition().ordinal();
            npc.maidenCrab.scuffed = crab.isScuffed();
            return;
        }

        if (properties instanceof Nylo.Properties) {
            var nylo = (Nylo.Properties) properties;
            npc.nylo = new Event.Nylo();
            npc.nylo.wave = nylo.getWave();
            npc.nylo.parentRoomId = nylo.getParentRoomId();
            npc.nylo.big = nylo.isBig();
            npc.nylo.style = nylo.getStyle().ordinal();
            npc.nylo.spawnType = nylo.getSpawnType().ordinal();
            return;
        }

        if (properties instanceof VerzikCrab.Properties) {
            var crab = (VerzikCrab.Properties) properties;
            npc.verzikCrab = new Event.VerzikCrab();
            npc.verzikCrab.phase = crab.getPhase().ordinal();
            npc.verzikCrab.spawn = crab.getSpawn().ordinal();
        }
    }
}

